# Background is 5. Let's find connected components of non-5 cells
from collections import deque

def get_neighbors(r, c, grid):
    rows, cols = len(grid), len(grid[0])
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != 5:
            yield (nr, nc)

# Flood find connected components
visited = set()
components = []
for i in range(len(grid)):
    for j in range(len(grid[0])):
        if grid[i][j] != 5 and (i, j) not in visited:
            component = []
            queue = deque([(i, j)])
            while queue:
                r, c = queue.popleft()
                if (r, c) in visited:
                    continue
                visited.add((r, c))
                component.append((r, c))
                for nr, nc in get_neighbors(r, c, grid):
                    if (nr, nc) not in visited:
                        queue.append((nr, nc))
            if component:
                components.append(component)

print(f"Found {len(components)} connected components of non-5 cells:")
