]

rows, cols = len(grid), len(grid[0])

# Count non-5 neighbors for each cell
output = []
for i in range(rows):
    row_out = []
    for j in range(cols):
        if grid[i][j] != 5:
            count = 0
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    ni, nj = i + dr, j + dc
                    if 0 <= ni < rows and 0 <= nj < cols and grid[ni][nj] != 5:
                        count += 1
            row_out.append(count)
        else:
            row_out.append(0)
    output.append(row_out)

print("Hypothesis 1 - neighbor counts:")
for row in output:
    print(row)

